-- Patient # / Case ID generated by PASIG. TBInsight never receives names or
-- date of birth — only these two IDs and the computed age.
ALTER TABLE tb_cases ADD COLUMN IF NOT EXISTS case_no TEXT;
ALTER TABLE tb_cases ADD COLUMN IF NOT EXISTS patient_no TEXT;

-- One row per Case ID: a re-sent case updates its row instead of inserting a duplicate.
CREATE UNIQUE INDEX IF NOT EXISTS uq_tb_cases_case_no ON tb_cases(case_no) WHERE case_no IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tb_cases_patient_no ON tb_cases(patient_no) WHERE patient_no IS NOT NULL;

-- duplicate_of_case_id is a self-referencing FK; without an index, deleting cases
-- (batch undo) checks it with a full table scan per deleted row.
CREATE INDEX IF NOT EXISTS idx_tb_cases_duplicate_of ON tb_cases(duplicate_of_case_id)
  WHERE duplicate_of_case_id IS NOT NULL;
